/** 平台配套资源类型：国家课 / 精品课 / 知识点微课包 / 课件 / 配套练习卷。 */
export type SmarteduResourceKind =
  | 'national_lesson'
  | 'elite_lesson'
  | 'knowledge_micro_lesson_package'
  | 'coursewares'
  | 'examinationpapers'

/** 一条平台配套资源（国家课/精品课/知识点微课/课件/练习卷）。 */
export interface SmarteduItem {
  readonly kind: SmarteduResourceKind
  /** 平台资源 id — classActivity 的 activityId / 详情页的 resourceId。 */
  readonly id: string
  /** 资源挂载的章节树叶子节点 id。 */
  readonly chapterId: string
  readonly title: string
}

export interface SmarteduCourseChapter {
  /** 平台章节树的章名（以平台为准，可能与旧版教材章名不同）。 */
  readonly title: string
  readonly items: readonly SmarteduItem[]
}

/** 一册教材在平台上的同步课程。 */
export interface SmarteduCourse {
  readonly stage: ExperimentStage
  readonly volume: string
  /** national_lesson teachingmaterialId — classActivity 的 teachingmaterialId。 */
  readonly teachingmaterialId: string
  readonly chapters: readonly SmarteduCourseChapter[]
}

